CREATE TYPE "AttendanceStatus" AS ENUM ('UNCONFIRMED','ATTENDED','MISSED','CANCELLED','EXCUSED');
CREATE TYPE "AttendanceSource" AS ENUM ('TIMETABLE_PROMPT','SELF_REPORTED','OCR_IMPORTED');
CREATE TYPE "StudySessionStatus" AS ENUM ('PLANNED','ACTIVE','COMPLETED','PARTIAL','CANCELLED','EXPIRED');
CREATE TYPE "StudyCompletionSource" AS ENUM ('TIMER_TRACKED','SELF_REPORTED','AUTO_CLOSED');
CREATE TYPE "CwaEvidenceMode" AS ENUM ('OFFICIAL','PROJECTED','ASSESSMENT_PREDICTION');
CREATE TABLE "attendance_records" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "user_id" UUID NOT NULL, "semester_id" UUID NOT NULL, "course_id" UUID, "timetable_block_id" UUID NOT NULL, "class_date" DATE NOT NULL, "scheduled_start" TIMESTAMP(3) NOT NULL, "scheduled_end" TIMESTAMP(3) NOT NULL, "status" "AttendanceStatus" NOT NULL DEFAULT 'UNCONFIRMED', "responded_at" TIMESTAMP(3), "source" "AttendanceSource" NOT NULL DEFAULT 'TIMETABLE_PROMPT', "notes" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("id"));
ALTER TABLE "attendance_records" ADD CONSTRAINT "attendance_records_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE, ADD CONSTRAINT "attendance_records_semester_id_fkey" FOREIGN KEY ("semester_id") REFERENCES "semesters"("id") ON DELETE CASCADE, ADD CONSTRAINT "attendance_records_course_id_fkey" FOREIGN KEY ("course_id") REFERENCES "courses"("id") ON DELETE SET NULL, ADD CONSTRAINT "attendance_records_timetable_block_id_fkey" FOREIGN KEY ("timetable_block_id") REFERENCES "timetable_blocks"("id") ON DELETE CASCADE;
CREATE UNIQUE INDEX "attendance_records_user_id_timetable_block_id_class_date_key" ON "attendance_records"("user_id","timetable_block_id","class_date");
CREATE TABLE "study_sessions" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "user_id" UUID NOT NULL, "semester_id" UUID NOT NULL, "course_id" UUID, "study_plan_item_id" UUID, "planned_start" TIMESTAMP(3), "planned_end" TIMESTAMP(3), "started_at" TIMESTAMP(3), "ended_at" TIMESTAMP(3), "duration_minutes" INTEGER NOT NULL DEFAULT 0, "status" "StudySessionStatus" NOT NULL DEFAULT 'PLANNED', "completion_source" "StudyCompletionSource", "last_heartbeat_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("id"));
ALTER TABLE "study_sessions" ADD CONSTRAINT "study_sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE, ADD CONSTRAINT "study_sessions_semester_id_fkey" FOREIGN KEY ("semester_id") REFERENCES "semesters"("id") ON DELETE CASCADE, ADD CONSTRAINT "study_sessions_course_id_fkey" FOREIGN KEY ("course_id") REFERENCES "courses"("id") ON DELETE SET NULL, ADD CONSTRAINT "study_sessions_study_plan_item_id_fkey" FOREIGN KEY ("study_plan_item_id") REFERENCES "study_plan_items"("id") ON DELETE SET NULL;
CREATE TABLE "cwa_evidence_records" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "user_id" UUID NOT NULL, "semester_id" UUID NOT NULL, "mode" "CwaEvidenceMode" NOT NULL, "value" DECIMAL(5,2) NOT NULL, "evidence" TEXT NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("id"));
ALTER TABLE "cwa_evidence_records" ADD CONSTRAINT "cwa_evidence_records_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE, ADD CONSTRAINT "cwa_evidence_records_semester_id_fkey" FOREIGN KEY ("semester_id") REFERENCES "semesters"("id") ON DELETE CASCADE;
